import { translations } from './translations.js';

const lang = ['de','en','bs'].includes(document.documentElement.lang) ? document.documentElement.lang : 'de';
const locale = {de:'de-AT',en:'en-GB',bs:'bs-BA'}[lang];
const tr = (key,vars={}) => {if(Number(vars.n)===1)key=({images:'imageOne',packageCount:'packageOne',checkoutIntro:'checkoutIntroOne',uploadDone:'uploadDoneOne'})[key]||key;return(translations[lang][key] || translations.de[key] || key).replace(/\{(\w+)\}/g,(_,k)=>String(vars[k]??''));};
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths = {
  lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
  heart:'<path d="M20.5 4.5a5.2 5.2 0 0 0-7.4 0L12 5.6l-1.1-1.1a5.2 5.2 0 0 0-7.4 7.4L12 20.4l8.5-8.5a5.2 5.2 0 0 0 0-7.4Z"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v5h16v-5"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  back:'<path d="M20 12H4m6-6-6 6 6 6"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="2"/><path d="m21 16-6-6-9 11"/>',
  eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
  fullscreen:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',
  logout:'<path d="M9 4H4v16h5m6-12 4 4-4 4m-7-4h11"/>',
  plus:'<path d="M12 4v16M4 12h16"/>',
  bag:'<path d="M5 7h14l2 14H3L5 7Z"/><path d="M8 7V5a4 4 0 0 1 8 0v2"/>',
  mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m3 7 9 6 9-6"/>',
  camera:'<path d="M7 5h10l2 3h3v13H2V8h3l2-3Z"/><circle cx="12" cy="14" r="4"/>',
  chevron:'<path d="m9 5 7 7-7 7"/>'
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${iconPaths[name]||iconPaths.image}</svg>`;
const btn = (text,action,extra='',kind='',symbol='') => `<button type="button" class="portal-btn ${kind}" data-action="${action}" ${extra}>${symbol?icon(symbol):''}${esc(text)}</button>`;
const links = {terms:lang==='de'?'terms.html':`terms-${lang}.html`,privacy:lang==='de'?'privacy.html':`privacy-${lang}.html`};
const fmtDate = date => {if(!date)return '';const d=new Date(/^\d{4}-\d{2}-\d{2}$/.test(date)?date+'T12:00:00':date);return Number.isNaN(d.valueOf())?'':new Intl.DateTimeFormat(locale,{day:'numeric',month:'long',year:'numeric'}).format(d);};
const money = (cents,currency='EUR') => new Intl.NumberFormat(locale,{style:'currency',currency}).format(Number(cents)/100);
const app = document.querySelector('#portal-app');
const params = new URLSearchParams(location.search);
const candidateToken = params.get('token');
const authToken = !params.has('paypalOrder') && /^[a-f0-9]{64}$/i.test(candidateToken||'') ? candidateToken : null;
const authPurpose = params.get('purpose')==='reset'?'reset':'setup';
const pendingGallery = params.get('gallery');
if(authToken){params.delete('token');params.delete('purpose');history.replaceState(null,'',location.pathname+(params.size?'?'+params.toString():'')+location.hash);}
const state = {user:null,csrf:null,capabilities:{},galleries:[],detail:null,selected:new Set(),favourites:new Set(),ackFavourites:new Set(),favouriteVersion:0,favouriteQueue:Promise.resolve(),filter:'all',authMode:'login',admin:false,adminTab:'galleries',adminGalleryId:null,adminDetail:null,adminSelection:new Set(),orders:[],lightboxIndex:0,lightboxList:[],view:'login'};

class ApiError extends Error{constructor(status,data){super(data?.message||'Request failed');this.status=status;this.code=data?.code||data?.error;this.data=data;}}
function errorText(error){
  if(error instanceof ApiError){if(error.status===401)return tr(error.code==='invalid_credentials'?'errorAuth':'errorSession');if(error.status===403)return tr('errorForbidden');if(error.status===404||error.status===410)return tr('errorNotFound');if(error.status===429)return tr('errorRate');if(error.status===503||error.code?.includes?.('configured'))return tr('errorConfig');}
  if(error?.message?.startsWith('UI:'))return error.message.slice(3);
  return tr('errorGeneric');
}
async function api(path,options={}){
  const method=options.method||'GET',headers={Accept:'application/json',...options.headers};
  if(state.csrf&&method!=='GET')headers['X-CSRF-Token']=state.csrf;
  let body=options.body;
  if(body&&!(body instanceof FormData)){headers['Content-Type']='application/json';body=JSON.stringify(body);}
  const response=await fetch('/api'+path,{...options,method,headers,body,credentials:'same-origin',cache:'no-store'});
  let data;try{data=await response.json();}catch{throw new ApiError(response.status||503,{error:'connection_unavailable'});}
  if(!response.ok)throw new ApiError(response.status,data);
  return data;
}
let toastTimer;
function toast(message){const node=document.querySelector('#portal-toast');node.textContent=message;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,5000);}
function message(form,text,type='error'){let node=form.querySelector('.portal-form-message');if(!node){node=document.createElement('p');node.className='portal-form-message portal-message';node.setAttribute('role','status');form.append(node);}node.className='portal-form-message portal-message '+type;node.textContent=text;}
async function withBusy(form,fn){const buttons=[...form.querySelectorAll('button[type=submit]')];buttons.forEach(b=>b.disabled=true);form.setAttribute('aria-busy','true');try{await fn();}catch(error){message(form,errorText(error));}finally{if(form.isConnected){buttons.forEach(b=>b.disabled=false);form.removeAttribute('aria-busy');}}}
let fieldCounter=0;
function field(label,name,type='text',value='',attrs=''){const id=`p-${name}-${++fieldCounter}`;return `<div class="portal-field"><label for="${id}">${esc(label)}</label><input id="${id}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
function passwordField(label,name,attrs=''){return `<div class="portal-field"><label for="p-${name}">${esc(label)}</label><div class="portal-password"><input id="p-${name}" name="${name}" type="password" ${attrs}><button type="button" data-action="show-password" data-input="p-${name}" aria-label="${esc(tr('showPassword'))}" aria-pressed="false">${icon('eye')}</button></div></div>`;}
function setView(html){app.innerHTML=html;app.removeAttribute('aria-busy');document.querySelector('.portal-content').dataset.theme=state.view==='gallery'&&['warm','light','dark'].includes(state.detail?.gallery.theme)?state.detail.gallery.theme:'warm';}
const shootingTypes={school:'typeSchool',maternity:'typeMaternity',newborn:'typeNewborn',family:'typeFamily',portrait:'typePortrait',wedding:'typeWedding',combo:'typeCombo',other:'typeOther'};
function selectField(label,name,options,value){const id=`p-${name}-${++fieldCounter}`;return `<div class="portal-field"><label for="${id}">${esc(label)}</label><select id="${id}" name="${name}">${Object.entries(options).map(([option,key])=>`<option value="${option}" ${option===value?'selected':''}>${esc(tr(key))}</option>`).join('')}</select></div>`;}
function galleryControls(gallery={},appearance=false){return selectField(tr('shootingType'),'shootingType',shootingTypes,gallery.shootingType||'other')+selectField(tr('pricingMode'),'pricingMode',{gallery:'modeGallery',images:'modeImages'},gallery.pricingMode||'gallery')+(appearance?selectField(tr('theme'),'theme',{warm:'themeWarm',light:'themeLight',dark:'themeDark'},gallery.theme||'warm')+selectField(tr('gridLayout'),'gridLayout',{masonry:'layoutMasonry',grid:'layoutGrid'},gallery.gridLayout||'masonry')+field(tr('coverPosition'),'coverPosition','number',gallery.coverPosition??50,'required min="0" max="100" step="1"'):'');}
function authCard(){
  const mode=state.authMode,heading=mode==='login'?tr('loginTitle'):tr(mode==='setup'?'setup':'reset');
  return `<section class="portal-card portal-login-card" aria-labelledby="portal-auth-title"><h2 id="portal-auth-title">${esc(heading)}</h2><p>${esc(tr(mode==='login'?'loginIntro':mode==='setup'?'setupIntro':'resetIntro'))}</p><div class="portal-tabs" role="tablist" aria-label="${esc(tr('security'))}"><button type="button" role="tab" aria-selected="${mode==='login'}" data-action="auth-mode" data-mode="login">${esc(tr('login'))}</button><button type="button" role="tab" aria-selected="${mode!=='login'}" data-action="auth-mode" data-mode="setup">${esc(tr('setup'))}</button></div><form id="portal-login-form">${field(tr('email'),'email','email','',`autocomplete="email" required maxlength="254"`)}${mode==='login'?passwordField(tr('password'),'password','autocomplete="current-password" required'):''}<button type="submit" class="portal-btn block">${esc(tr(mode==='login'?'login':mode==='setup'?'requestSetup':'requestReset'))}${icon(mode==='login'?'arrow':'mail')}</button><div class="portal-underform">${mode==='login'?`<button type="button" class="portal-link-btn" data-action="auth-mode" data-mode="reset">${esc(tr('forgot'))}</button>`:`<button type="button" class="portal-link-btn" data-action="auth-mode" data-mode="login">${esc(tr('login'))}</button>`}<a class="portal-small" href="mailto:info@liza-memories-photography.com">${esc(tr('help'))}</a></div></form><p class="portal-secure-note">${icon('lock')}<span>${esc(tr('secureNote'))}</span></p></section>`;
}
function renderLogin(){state.view='login';setView(`<div class="portal-wrap portal-login"><section class="portal-welcome"><p class="portal-eyebrow">${icon('lock')}${esc(tr('private'))}</p><h1>${esc(tr('welcome'))}<em>${esc(tr('welcomeAccent'))}</em></h1><p class="portal-lead">${esc(tr('intro'))}</p><div class="portal-feature-row"><span>${icon('lock')}${esc(tr('protected'))}</span><span>${icon('heart')}${esc(tr('favourites'))}</span><span>${icon('download')}${esc(tr('downloads'))}</span></div><div class="portal-art" aria-hidden="true"><span>${icon('camera')}</span><span>${icon('heart')}</span></div></section>${authCard()}</div>`);}
function renderOffline(){setView(`<section class="portal-wrap"><div class="portal-empty portal-card">${icon('lock')}<h1>${esc(tr('offlineTitle'))}</h1><p>${esc(tr('offlineText'))}</p>${btn(tr('retry'),'retry','','','arrow')}<p class="portal-small" style="margin-top:20px"><a href="mailto:info@liza-memories-photography.com">${esc(tr('contact'))}</a></p></div></section>`);}
function renderSetPassword(){state.view='token';setView(`<div class="portal-wrap portal-login"><section class="portal-welcome"><p class="portal-eyebrow">${icon('lock')}${esc(tr('security'))}</p><h1>${esc(tr('setPasswordTitle'))}</h1><p class="portal-lead">${esc(tr('setPasswordIntro'))}</p></section><section class="portal-card portal-login-card"><h2>${esc(tr(authPurpose==='reset'?'reset':'setup'))}</h2><form id="portal-password-form">${passwordField(tr('newPassword'),'password','autocomplete="new-password" minlength="12" maxlength="128" required')}${passwordField(tr('repeatPassword'),'passwordRepeat','autocomplete="new-password" minlength="12" maxlength="128" required')}<p class="portal-small">${esc(tr('passwordHint'))}</p><button type="submit" class="portal-btn block">${esc(tr('savePassword'))}${icon('arrow')}</button></form></section></div>`);}
function topbar(title,subtitle='',back=false){return `<div class="portal-topbar"><div>${back?`<button type="button" class="portal-link-btn" data-action="home">${icon('back')} ${esc(tr('backGalleries'))}</button>`:''}<h1>${esc(title)}</h1>${subtitle?`<p class="portal-small">${esc(subtitle)}</p>`:''}</div><div class="portal-top-actions"><span class="portal-avatar" aria-hidden="true">${esc((state.user?.name||state.user?.email||'L').charAt(0).toUpperCase())}</span>${state.user?.role==='admin'?btn(tr(state.admin?'clientView':'admin'),'toggle-admin','','secondary'):''}${btn(tr('signOut'),'logout','','subtle','logout')}</div></div>`;}
async function loadSession(){const data=await api('/session');Object.assign(state,{user:data.user,csrf:data.csrf,capabilities:data.capabilities||{}});return data;}
async function loadHome(){state.detail=null;state.selected.clear();const data=await api('/galleries');state.galleries=data.galleries||[];const orders=await api('/orders');state.orders=orders.orders||[];renderHome();}
function renderHome(){
  state.view='home';
  const list=state.galleries.map(g=>`<article class="portal-gallery-tile"><a href="?gallery=${encodeURIComponent(g.id)}" data-action="open-gallery" data-id="${esc(g.id)}"><div class="portal-tile-photo">${g.coverUrl?`<img src="${esc(g.coverUrl)}" alt="${esc(g.name)}" loading="lazy" decoding="async">`:icon('image')}</div><div class="portal-tile-copy"><h2>${esc(g.name)}</h2><p>${esc(fmtDate(g.date))}</p><div class="portal-count"><span>${esc(tr('images',{n:g.imageCount||0}))}</span><span>${esc(tr('openGallery'))} ${icon('arrow')}</span></div></div></a></article>`).join('');
  setView(`<div class="portal-wrap">${topbar(tr('myGalleries'),tr('hello',{name:state.user.name||state.user.email}))}${list?`<div class="portal-gallery-list">${list}</div>`:`<section class="portal-empty">${icon('image')}<h2>${esc(tr('noGalleries'))}</h2><p>${esc(tr('noGalleriesText'))}</p></section>`}${ordersHtml(state.orders)}</div>`);
}
async function openGallery(id){const [detail,orders]=await Promise.all([api('/galleries/'+encodeURIComponent(id)),api('/orders')]);state.detail=detail;state.orders=orders.orders||[];state.favourites=new Set(detail.favorites||[]);state.ackFavourites=new Set(state.favourites);state.selected.clear();state.filter='all';state.admin=false;params.set('gallery',id);history.replaceState(null,'',location.pathname+'?'+params.toString());renderGallery();document.querySelector('#main-content').scrollIntoView({behavior:'instant'});}
function visibleImages(){return(state.detail?.images||[]).filter(image=>state.filter!=='favourites'||state.favourites.has(image.id));}
function photoHtml(image,index){return `<figure class="portal-photo${state.selected.has(image.id)?' selected':''}" data-photo-id="${esc(image.id)}"><button type="button" class="portal-photo-open" data-action="open-lightbox" data-id="${esc(image.id)}" aria-label="${esc(tr('photoOpen',{n:index+1}))}"><img src="${esc(image.previewUrl)}" alt="${esc(image.title||tr('photoOpen',{n:index+1}))}" width="${Number(image.width)||1000}" height="${Number(image.height)||1000}" loading="lazy" decoding="async"></button><span class="portal-photo-num" aria-hidden="true">${String(index+1).padStart(2,'0')}</span><div class="portal-photo-tools"><button type="button" class="portal-select" data-action="select-image" data-id="${esc(image.id)}" aria-label="${esc(tr(state.selected.has(image.id)?'deselectPhoto':'selectPhoto'))}" aria-pressed="${state.selected.has(image.id)}">${icon('check')}</button><button type="button" class="portal-fav" data-action="favorite" data-id="${esc(image.id)}" aria-label="${esc(tr(state.favourites.has(image.id)?'favoriteRemove':'favoriteAdd'))}" aria-pressed="${state.favourites.has(image.id)}">${icon('heart')}</button></div></figure>`;}
function renderGallery(){
  state.view='gallery';const {gallery,images}=state.detail,shown=visibleImages();
  setView(`<div class="portal-wrap">${topbar(tr('title'),'',true)}<section class="portal-gallery-head${gallery.coverUrl?'':' no-photo'}" aria-label="${esc(gallery.name)}">${gallery.coverUrl?`<img src="${esc(gallery.coverUrl)}" alt="" fetchpriority="high">`:''}<div class="portal-cover-copy"><p class="portal-eyebrow">LiZa Memories Photography</p><h1>${esc(gallery.name)}</h1><p>${esc(fmtDate(gallery.date))}${gallery.date?' · ':''}${esc(tr('images',{n:images.length}))}</p></div></section>${gallery.description?`<p class="portal-gallery-description">${esc(gallery.description)}</p>`:''}<div class="portal-toolbar"><div class="portal-filter" role="group" aria-label="${esc(tr('photos'))}"><button type="button" data-action="filter" data-filter="all" aria-pressed="${state.filter==='all'}">${icon('grid')}${esc(tr('allPhotos'))}</button><button type="button" data-action="filter" data-filter="favourites" aria-pressed="${state.filter==='favourites'}">${icon('heart')}<span id="p-favourites-count">${esc(tr('favouritesCount',{n:state.favourites.size}))}</span></button></div><div class="portal-tool-actions"><span class="portal-total">${esc(tr('images',{n:shown.length}))}</span>${btn(tr(state.filter==='favourites'?'selectFavourites':'selectAll'),'select-all','','secondary','check')}${btn(tr('buyPhotos'),'checkout',state.selected.size?'':'disabled','','bag')}</div></div><div class="portal-photo-grid" id="portal-photo-grid">${shown.map(photoHtml).join('')}</div>${!shown.length?`<section class="portal-empty">${icon(state.filter==='favourites'?'heart':'image')}<h2>${esc(tr(state.filter==='favourites'?'noFavourites':'noImages'))}</h2><p>${esc(tr(state.filter==='favourites'?'noFavouritesText':'noImagesText'))}</p></section>`:''}<div class="portal-selection-dock" id="portal-selection-dock" ${state.selected.size?'':'hidden'}><p><strong id="p-selected-count">${esc(tr('selectedCount',{n:state.selected.size}))}</strong></p><div class="portal-tool-actions">${btn(tr('clearSelection'),'clear-selection','','secondary')}${btn(tr('downloadSelected'),'download','','secondary','download')}${btn(tr('buyPhotos'),'checkout','','','bag')}</div></div>${ordersHtml(state.orders.filter(o=>o.galleryId===gallery.id))}<p class="portal-small" style="margin:32px 0 0">${esc(tr('digitalOnly'))}</p></div>`);
  const grid=document.getElementById('portal-photo-grid');grid.classList.toggle('portal-equal-grid',gallery.gridLayout==='grid');
  const cover=document.querySelector('.portal-gallery-head>img');if(cover)cover.style.objectPosition=`50% ${Math.max(0,Math.min(100,Number(gallery.coverPosition??50)))}%`;
  if(gallery.pricingMode!=='images'){
    const hasGalleryPackage=state.detail.packages?.some(pkg=>pkg.imageCount===0&&pkg.active!==false);
    document.querySelectorAll('[data-action="checkout"]').forEach(button=>{if(hasGalleryPackage){button.dataset.action='buy-gallery';button.disabled=false;button.innerHTML=icon('bag')+esc(tr('buyGallery'));}else button.remove();});
    if(!hasGalleryPackage)document.querySelector('.portal-toolbar').insertAdjacentHTML('afterend',`<p class="portal-gallery-description">${esc(tr('galleryNoPrice'))}</p>`);
  }
  if(images.length>30)document.querySelector('.portal-wrap').insertAdjacentHTML('beforeend',`<p class="portal-small">${esc(tr('downloadBatchHint'))}</p>`);
}
function syncSelectionUI(){document.querySelectorAll('[data-photo-id]').forEach(node=>{const id=node.dataset.photoId,selected=state.selected.has(id),favorite=state.favourites.has(id);node.classList.toggle('selected',selected);const sb=node.querySelector('.portal-select'),fb=node.querySelector('.portal-fav');if(sb){sb.setAttribute('aria-pressed',selected);sb.setAttribute('aria-label',tr(selected?'deselectPhoto':'selectPhoto'));}if(fb){fb.setAttribute('aria-pressed',favorite);fb.setAttribute('aria-label',tr(favorite?'favoriteRemove':'favoriteAdd'));}});const count=document.querySelector('#p-selected-count');if(count)count.textContent=tr('selectedCount',{n:state.selected.size});const dock=document.querySelector('#portal-selection-dock');if(dock)dock.hidden=!state.selected.size;document.querySelectorAll('[data-action="checkout"]').forEach(button=>button.disabled=!state.selected.size);const favcount=document.querySelector('#p-favourites-count');if(favcount)favcount.textContent=tr('favouritesCount',{n:state.favourites.size});syncLightbox();}
function toggleSelected(id){if(state.selected.has(id))state.selected.delete(id);else state.selected.add(id);syncSelectionUI();}
function refreshFavouriteGrid(){if(state.view!=='gallery'||state.filter!=='favourites')return;const grid=document.getElementById('portal-photo-grid');if(!grid)return;grid.innerHTML=visibleImages().map(photoHtml).join('');let empty=document.getElementById('portal-favourites-empty');if(!visibleImages().length&&!empty){empty=document.createElement('section');empty.id='portal-favourites-empty';empty.className='portal-empty';empty.innerHTML=icon('heart')+`<h2>${esc(tr('noFavourites'))}</h2><p>${esc(tr('noFavouritesText'))}</p>`;grid.after(empty);}else if(visibleImages().length)empty?.remove();}
function toggleFavourite(id){if(state.favourites.has(id))state.favourites.delete(id);else state.favourites.add(id);const snapshot=[...state.favourites],version=++state.favouriteVersion,galleryId=state.detail.gallery.id;refreshFavouriteGrid();syncSelectionUI();state.favouriteQueue=state.favouriteQueue.catch(()=>{}).then(async()=>{try{await api(`/galleries/${encodeURIComponent(galleryId)}/favorites`,{method:'PUT',body:{imageIds:snapshot}});if(state.detail?.gallery.id===galleryId)state.ackFavourites=new Set(snapshot);}catch(error){if(version===state.favouriteVersion&&state.detail?.gallery.id===galleryId){state.favourites=new Set(state.ackFavourites);refreshFavouriteGrid();syncSelectionUI();}toast(errorText(error));}});}
function orderStatus(order){return ['paid','completed','released'].includes(order.status)?(order.receiptSent?'orderPaid':'receiptPending'):order.status==='refunded'?'refunded':order.status==='cancelled'?'orderCancelled':order.status==='failed'?'orderFailed':'orderPending';}
function ordersHtml(orders){
  const cards=orders.map(order=>{
    const withdraw=['pending','paid'].includes(order.status)&&!order.withdrawalRequested;
    return `<article class="portal-order"><div><h3>${esc(order.packageName||order.galleryName||tr('photos'))}</h3><p>${esc(tr('orderNumber',{id:order.id}))} · ${esc(fmtDate(order.createdAt))}</p>${order.galleryName?`<p>${esc(order.galleryName)}</p>`:''}<a href="/api/orders/${encodeURIComponent(order.id)}/receipt" class="portal-small" download>${esc(tr('receipt'))}</a>${withdraw?`<div><button type="button" class="portal-link-btn" data-action="withdraw" data-id="${esc(order.id)}">${esc(tr('withdrawal'))}</button></div>`:''}${order.withdrawalRequested?`<p class="portal-small">${esc(tr('withdrawalRequested'))}</p>`:''}</div><div class="portal-order-meta"><strong>${esc(money(order.amountCents,order.currency))}</strong><span class="portal-badge ${orderStatus(order)==='orderPaid'?'paid':''}">${esc(tr(orderStatus(order)))}</span>${order.paymentMethod==='transfer'&&orderStatus(order)==='orderPending'?`<div><button type="button" class="portal-link-btn" data-action="order-bank" data-id="${esc(order.id)}">${esc(tr('transfer'))}</button></div>`:''}</div></article>`;
  }).join('');
  return `<section class="portal-orders"><h2>${esc(tr('myOrders'))}</h2>${orders.length?`<div class="portal-order-list">${cards}</div>`:`<p class="portal-small">${esc(tr('noOrders'))}</p>`}</section>`;
}
let activeDialog=null,previousFocus=null;
function createDialog(html,className=''){if(activeDialog)closeDialog();previousFocus=document.activeElement;const dialog=document.createElement('dialog');dialog.className='portal-dialog '+className;dialog.innerHTML=html;dialog.setAttribute('aria-modal','true');dialog.setAttribute('aria-labelledby','p-dialog-title');document.body.append(dialog);dialog.addEventListener('click',onAction);dialog.addEventListener('submit',onSubmit);dialog.addEventListener('change',onChange);dialog.addEventListener('cancel',()=>{});dialog.addEventListener('close',()=>{if(activeDialog===dialog)activeDialog=null;dialog.remove();previousFocus?.focus?.({preventScroll:true});});activeDialog=dialog;dialog.showModal();return dialog;}
function closeDialog(){if(activeDialog){if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});activeDialog.close();}}
function dialogTop(title){return `<div class="portal-modal-top"><h2 id="p-dialog-title">${esc(title)}</h2><button type="button" class="portal-icon-btn" data-action="close-dialog" aria-label="${esc(tr('close'))}">${icon('close')}</button></div>`;}
function openLightbox(id){state.lightboxList=visibleImages();state.lightboxIndex=state.lightboxList.findIndex(image=>image.id===id);if(state.lightboxIndex<0)return;const dialog=createDialog(`<div class="portal-lightbox-header"><p id="p-dialog-title"></p><div class="portal-lightbox-actions"><button type="button" class="portal-icon-btn portal-fav" data-action="lightbox-favorite" aria-label="${esc(tr('favoriteAdd'))}" aria-pressed="false">${icon('heart')}</button><button type="button" class="portal-icon-btn" data-action="fullscreen" aria-label="${esc(tr('fullscreen'))}">${icon('fullscreen')}</button><button type="button" class="portal-icon-btn" data-action="close-dialog" aria-label="${esc(tr('close'))}">${icon('close')}</button></div></div><button type="button" class="portal-lightbox-nav prev" data-action="previous" aria-label="${esc(tr('previous'))}">${icon('back')}</button><div class="portal-lightbox-stage"><span class="portal-spinner" aria-hidden="true"></span><img id="p-lightbox-image" alt=""><p class="portal-message error" id="p-lightbox-error" hidden></p></div><button type="button" class="portal-lightbox-nav next" data-action="next" aria-label="${esc(tr('next'))}">${icon('arrow')}</button><div class="portal-lightbox-caption"><p id="p-lightbox-caption"></p><span id="p-lightbox-position"></span> · <button type="button" data-action="lightbox-select" id="p-lightbox-select">${esc(tr('selectPhoto'))}</button></div>`,'portal-lightbox');let startX=0,startY=0;dialog.addEventListener('pointerdown',event=>{if(event.target.tagName==='IMG'){startX=event.clientX;startY=event.clientY;}});dialog.addEventListener('pointerup',event=>{if(event.target.tagName==='IMG'){const dx=event.clientX-startX,dy=event.clientY-startY;if(Math.abs(dx)>55&&Math.abs(dy)<80)moveLightbox(dx<0?1:-1);}});syncLightbox(true);}
function syncLightbox(load=false){if(!activeDialog?.classList.contains('portal-lightbox'))return;const image=state.lightboxList[state.lightboxIndex];if(!image)return;const favorite=state.favourites.has(image.id),selected=state.selected.has(image.id);const fb=activeDialog.querySelector('.portal-fav');fb.setAttribute('aria-pressed',favorite);fb.setAttribute('aria-label',tr(favorite?'favoriteRemove':'favoriteAdd'));activeDialog.querySelector('#p-dialog-title').textContent=state.detail.gallery.name;activeDialog.querySelector('#p-lightbox-caption').textContent=image.title||'';activeDialog.querySelector('#p-lightbox-position').textContent=tr('imagePosition',{n:state.lightboxIndex+1,total:state.lightboxList.length});activeDialog.querySelector('#p-lightbox-select').textContent=tr(selected?'deselectPhoto':'selectPhoto');activeDialog.querySelector('.prev').disabled=state.lightboxList.length<2;activeDialog.querySelector('.next').disabled=state.lightboxList.length<2;if(load){const img=activeDialog.querySelector('#p-lightbox-image'),spinner=activeDialog.querySelector('.portal-spinner'),error=activeDialog.querySelector('#p-lightbox-error');spinner.hidden=false;error.hidden=true;img.hidden=false;img.onload=()=>spinner.hidden=true;img.onerror=()=>{spinner.hidden=true;img.hidden=true;error.textContent=tr('imageLoadError');error.hidden=false;};img.alt=image.title||tr('photoOpen',{n:state.lightboxIndex+1});img.src=image.previewUrl;}}
function moveLightbox(delta){state.lightboxIndex=(state.lightboxIndex+delta+state.lightboxList.length)%state.lightboxList.length;syncLightbox(true);}
document.addEventListener('keydown',event=>{if(!activeDialog?.classList.contains('portal-lightbox'))return;if(event.key==='ArrowLeft'){event.preventDefault();moveLightbox(-1);}if(event.key==='ArrowRight'){event.preventDefault();moveLightbox(1);}});

function openCheckout(){
  if(!state.selected.size)return toast(tr('chooseImages'));
  const allCount=state.detail.images.length,count=state.selected.size;
  const packages=(state.detail.packages||[]).filter(pkg=>(pkg.imageCount>0&&count%pkg.imageCount===0)||(pkg.imageCount===0&&count===allCount)).map(pkg=>({...pkg,quantity:pkg.imageCount>0?count/pkg.imageCount:1}));
  const available=state.capabilities,hasPayment=available.email&&(available.transferConfigured||available.stripe||available.paypal);
  createDialog(`<div class="portal-modal-copy">${dialogTop(tr('checkoutTitle'))}<p class="portal-small">${esc(tr('checkoutIntro',{n:count}))}</p><form id="portal-order-form">${packages.length?packages.map((pkg,index)=>`<label class="portal-package"><input type="radio" name="packageId" value="${esc(pkg.id)}" ${index===0?'checked':''} required><span><strong>${esc(pkg.name)}</strong><small>${esc(tr(pkg.imageCount===0?'packageAll':'packageCount',{n:count}))}${pkg.quantity>1?' · '+esc(pkg.quantity+' × '+money(pkg.priceCents,pkg.currency)):''}</small></span><b>${esc(money(pkg.priceCents*pkg.quantity,pkg.currency))}</b></label>`).join(''):`<p class="portal-message">${esc(tr('noPackage'))}</p>`}<p class="portal-small">${esc(tr('digitalOnly'))}</p><p class="portal-small">${esc(tr('vat'))}</p><h3 style="font-size:25px;margin-top:25px">${esc(tr('paymentMethod'))}</h3><div class="portal-payments">${[['transfer','transferConfigured'],['stripe','stripe'],['paypal','paypal']].filter(([,key])=>available[key]).map(([method,key])=>`<label><input type="radio" name="paymentMethod" value="${method}" ${!available[key]?'disabled':method==='transfer'?'checked':''} required><span>${esc(tr(method))}${!available[key]?`<small style="display:block">${esc(tr('unavailablePayment'))}</small>`:''}</span></label>`).join('')}</div>${!hasPayment?`<p class="portal-message">${esc(tr('noPayment'))}</p>`:''}<label class="portal-check"><input type="checkbox" name="termsAccepted" required><span>${tr('termsConsent',links)}</span></label><label class="portal-check"><input type="checkbox" name="digitalConsent" required><span>${tr('digitalConsent',links)}</span></label><button class="portal-btn block" type="submit" ${packages.length&&hasPayment?'':'disabled'}>${esc(tr('orderButton'))}${icon('arrow')}</button></form></div>`);
  if(!available.transferConfigured){const first=activeDialog.querySelector('input[name="paymentMethod"]:not(:disabled)');if(first)first.checked=true;}
}
function showBank(order){
  const bank=state.capabilities.transfer;
  const showQr=bank&&order.paymentMethod==='transfer'&&order.status==='pending'&&order.amountCents>0;
  const dialog=createDialog(`<div class="portal-modal-copy">${dialogTop(tr('orderSuccess'))}<p>${esc(tr('transferInstruction'))}</p><div class="portal-bank">${bank?`<dl><dt>${esc(tr('bankRecipient'))}</dt><dd>${esc(bank.recipient)}</dd><dt>IBAN</dt><dd>${esc(bank.iban)}</dd>${bank.bic?`<dt>BIC</dt><dd>${esc(bank.bic)}</dd>`:''}<dt>${esc(tr('total'))}</dt><dd>${esc(money(order.amountCents,order.currency))}</dd><dt>${esc(tr('bankReference'))}</dt><dd>${esc(order.id)}</dd></dl>`:`<p>${esc(tr('bankMissing'))}</p>`}</div>${showQr?`<section class="portal-bank-qr"><canvas id="p-bank-qr" role="img" aria-label="${esc(tr('bankQrAlt'))}"></canvas><div><h3>${esc(tr('bankQrTitle'))}</h3><p class="portal-small">${esc(tr('bankQrHint'))}</p>${btn(tr('saveBankQr'),'save-bank-qr','','secondary','download')}</div></section><p class="portal-message" id="p-bank-qr-error" hidden></p>`:''}<p class="portal-small" style="margin-top:20px">${esc(tr('orderNumber',{id:order.id}))}</p>${btn(tr('continueGallery'),'close-dialog','','block','arrow')}</div>`);
  if(showQr){try{if(!window.LizaBankQr)throw new Error('QR module unavailable');window.LizaBankQr.draw(dialog.querySelector('#p-bank-qr'),{...bank,amountCents:order.amountCents,reference:order.id});}catch{dialog.querySelector('.portal-bank-qr').hidden=true;const error=dialog.querySelector('#p-bank-qr-error');error.hidden=false;error.textContent=tr('bankQrUnavailable');}}
}

const crcTable=Uint32Array.from({length:256},(_,n)=>{let crc=n;for(let i=0;i<8;i++)crc=(crc&1)?0xedb88320^(crc>>>1):crc>>>1;return crc>>>0;});
function crc32(bytes){let crc=0xffffffff;for(const byte of bytes)crc=crcTable[(crc^byte)&255]^(crc>>>8);return(crc^0xffffffff)>>>0;}
function zipFiles(files){const parts=[],central=[],encoder=new TextEncoder();let offset=0;const now=new Date(),time=(now.getHours()<<11)|(now.getMinutes()<<5)|(now.getSeconds()>>1),date=((now.getFullYear()-1980)<<9)|((now.getMonth()+1)<<5)|now.getDate();for(const file of files){const name=encoder.encode(file.name),crc=crc32(file.bytes),local=new Uint8Array(30+name.length),lv=new DataView(local.buffer);lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x800,true);lv.setUint16(10,time,true);lv.setUint16(12,date,true);lv.setUint32(14,crc,true);lv.setUint32(18,file.bytes.length,true);lv.setUint32(22,file.bytes.length,true);lv.setUint16(26,name.length,true);local.set(name,30);parts.push(local,file.bytes);const c=new Uint8Array(46+name.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint16(12,time,true);cv.setUint16(14,date,true);cv.setUint32(16,crc,true);cv.setUint32(20,file.bytes.length,true);cv.setUint32(24,file.bytes.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);c.set(name,46);central.push(c);offset+=local.length+file.bytes.length;}const cdSize=central.reduce((total,part)=>total+part.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,cdSize,true);ev.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'});}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function safeFilename(name,defaultName){return String(name||defaultName).replace(/[<>:"/\\|?*\u0000-\u001f]/g,'_').replace(/^\.+/,'').slice(0,160)||defaultName;}
async function downloadSelection(){
  const images=state.detail.images.filter(image=>state.selected.has(image.id));if(!images.length)return toast(tr('chooseImages'));if(images.some(image=>!image.downloadAllowed))return toast(tr('downloadLocked'));if(images.length>30)return toast(tr('downloadLimit'));
  const dialog=createDialog(`<div class="portal-modal-copy">${dialogTop(tr('downloadPreparing'))}<p id="p-download-progress" class="portal-small"></p><div class="portal-download-progress"><span style="width:0%"></span></div></div>`);let size=0;const files=[];
  try{for(const [index,image] of images.entries()){if(!dialog.isConnected)return;const response=await fetch(image.originalUrl,{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw new ApiError(response.status,{});const length=Number(response.headers.get('Content-Length')||0);if(size+length>300*1024*1024)throw new Error('UI:'+tr('downloadSize'));const bytes=new Uint8Array(await response.arrayBuffer());size+=bytes.length;if(size>300*1024*1024)throw new Error('UI:'+tr('downloadSize'));const ext={'image/jpeg':'.jpg','image/png':'.png','image/webp':'.webp'}[response.headers.get('Content-Type')?.split(';')[0]]||'.jpg';let name=safeFilename(image.title,'LiZa-'+String(index+1).padStart(3,'0'));name=name.replace(/\.(jpe?g|png|webp)$/i,'')+ext;files.push({name:String(index+1).padStart(3,'0')+'-'+name,bytes});dialog.querySelector('#p-download-progress').textContent=tr('downloadProgress',{n:index+1,total:images.length});dialog.querySelector('.portal-download-progress span').style.width=(index+1)/images.length*100+'%';}
    const filename=safeFilename(state.detail.gallery.name,'LiZa-Memories');if(files.length===1)downloadBlob(new Blob([files[0].bytes]),files[0].name);else downloadBlob(zipFiles(files),filename+'.zip');closeDialog();toast(tr('downloadStarted'));
  }catch(error){if(dialog.isConnected){const progress=dialog.querySelector('#p-download-progress');progress.className='portal-message error';progress.textContent=errorText(error)+(error?.message==='UI:'+tr('downloadSize')?' '+tr('downloadBatchHint'):'');}}
}

async function loadAdmin(id=state.adminGalleryId){
  if(id!==state.adminGalleryId)state.adminSelection.clear();
  state.admin=true;state.view='admin';const [galleryData,orderData]=await Promise.all([api('/admin/galleries'),api('/admin/orders')]);state.adminGalleries=galleryData.galleries||[];state.adminOrders=orderData.orders||[];
  if(state.adminTab==='galleries'&&state.adminGalleries.length){state.adminGalleryId=state.adminGalleries.find(g=>g.id===id)?.id||state.adminGalleries[0].id;state.adminDetail=await api('/galleries/'+encodeURIComponent(state.adminGalleryId));}else state.adminDetail=null;
  renderAdmin();
}
function renderAdmin(){
  const galleries=state.adminGalleries||[];
  setView(`<div class="portal-wrap">${topbar(tr('admin'),'LiZa Memories Photography')}<div class="portal-admin-tabs" role="tablist" aria-label="${esc(tr('admin'))}"><button role="tab" aria-selected="${state.adminTab==='galleries'}" data-action="admin-tab" data-tab="galleries">${icon('grid')} ${esc(tr('manageGalleries'))}</button><button role="tab" aria-selected="${state.adminTab==='orders'}" data-action="admin-tab" data-tab="orders">${icon('bag')} ${esc(tr('manageOrders'))} (${state.adminOrders?.length||0})</button></div>${state.adminTab==='orders'?adminOrdersHtml():`<div class="portal-admin-layout"><aside class="portal-admin-sidebar" aria-label="${esc(tr('manageGalleries'))}">${btn(tr('createGallery'),'create-gallery','','','plus')}${galleries.map(g=>`<button type="button" class="${g.id===state.adminGalleryId?'active':''}" data-action="admin-gallery" data-id="${esc(g.id)}">${esc(g.name)}<small>${esc(tr(g.published?'published':'draft'))} · ${esc(tr('images',{n:g.imageCount||0}))}</small></button>`).join('')}</aside><div class="portal-admin-editor">${state.adminDetail?adminEditorHtml():`<section class="portal-empty portal-card">${icon('camera')}<h2>${esc(tr('noAdminGalleries'))}</h2><p>${esc(tr('noAdminGalleriesText'))}</p>${btn(tr('createGallery'),'create-gallery','','','plus')}</section>`}</div></div>`}</div>`);
  if(state.adminTab==='galleries'&&state.adminDetail){const lists=document.querySelectorAll('.portal-admin-editor .portal-admin-list');lists[0]?.querySelectorAll('li').forEach((li,index)=>{const member=state.adminDetail.members?.[index];if(member)li.insertAdjacentHTML('beforeend',btn(tr('revoke'),'revoke-member',`data-id="${esc(member.id)}"`,'secondary'));});lists[1]?.querySelectorAll('li').forEach((li,index)=>{const pkg=state.adminDetail.packages?.[index];if(pkg)li.insertAdjacentHTML('beforeend',btn(tr('edit'),'edit-package',`data-id="${esc(pkg.id)}"`,'secondary'));});}
  if(state.adminTab==='galleries'&&state.adminDetail){
    const gallery=state.adminDetail.gallery;
    document.querySelector('#portal-gallery-settings .portal-form-grid').insertAdjacentHTML('beforeend',galleryControls(gallery,true));
    const packageForm=document.querySelector('#portal-package-form');
    packageForm.insertAdjacentHTML('beforebegin',`<p class="portal-small">${esc(tr(gallery.pricingMode==='images'?'schoolPricingIntro':'galleryPricingIntro'))}</p>`);
    if(gallery.pricingMode!=='images'){packageForm.elements.packageName.value=tr('galleryPackageName');packageForm.elements.imageCount.value='0';packageForm.elements.price.value='';}
    const thumbs=document.querySelector('.portal-admin-thumbs');
    thumbs.insertAdjacentHTML('beforebegin',`<div class="portal-admin-photo-actions">${btn(tr('selectAllAdmin'),'admin-select-all','','secondary','check')}${btn(tr('clearAdmin'),'admin-clear-selection','','secondary')}<span class="portal-small" id="p-admin-selection-count">${esc(tr('selectedCount',{n:state.adminSelection.size}))}</span></div>`);
  }
  if(!state.capabilities.transferConfigured)document.querySelector('.portal-admin-tabs').insertAdjacentHTML('beforebegin',`<p class="portal-message">${esc(tr('bankAdminMissing'))}</p>`);
}
function adminEditorHtml(){
  const {gallery,images=[],packages=[],members=[]}=state.adminDetail;
  return `<section class="portal-card"><p class="portal-eyebrow">${esc(tr(gallery.published?'published':'draft'))}</p><h2>${esc(gallery.name)}</h2><form id="portal-gallery-settings"><div class="portal-form-grid">${field(tr('galleryName'),'name','text',gallery.name,'required maxlength="160"')}${field(tr('galleryDate'),'date','date',gallery.date?.slice(0,10)||'','required')}<div class="portal-field wide"><label for="p-description">${esc(tr('description'))}</label><textarea name="description" id="p-description" maxlength="2000">${esc(gallery.description||'')}</textarea></div><div class="portal-field"><label for="p-coverImageId">${esc(tr('coverImage'))}</label><select name="coverImageId" id="p-coverImageId"><option value="">${esc(tr('noCover'))}</option>${images.map(image=>`<option value="${esc(image.id)}" ${image.id===gallery.coverImageId?'selected':''}>${esc(image.title||image.id)}</option>`).join('')}</select></div>${field(tr('expiry'),'expiresAt','date',gallery.expiresAt?.slice(0,10)||'')}</div><label class="portal-check"><input type="checkbox" name="published" ${gallery.published?'checked':''}><span>${esc(tr('publishConsent'))}</span></label><button class="portal-btn" type="submit">${esc(tr('saveGallery'))}${icon('check')}</button></form></section><section class="portal-card"><h3>${esc(tr('customerAccess'))}</h3><p class="portal-small">${esc(tr('accessIntro'))}</p><form id="portal-member-form" class="portal-inline-form">${field(tr('customerName'),'memberName','text','','required maxlength="100"')}${field(tr('email'),'memberEmail','email','','required maxlength="254"')}<button class="portal-btn" type="submit">${esc(tr('addCustomer'))}</button></form><ul class="portal-admin-list">${members.length?members.map(member=>`<li><span>${esc(member.name||member.email)}<small>${esc(member.email)}</small></span>${btn(tr('sendInvite'),'invite',`data-email="${esc(member.email)}" ${state.capabilities.email?'':'disabled'}`,'secondary','mail')}</li>`).join(''):`<li>${esc(tr('noMembers'))}</li>`}</ul>${!state.capabilities.email?`<p class="portal-message">${esc(tr('inviteUnavailable'))}</p>`:''}</section><section class="portal-card"><h3>${esc(tr('packages'))}</h3><form id="portal-package-form" class="portal-inline-form">${field(tr('packageName'),'packageName','text','','required maxlength="100"')}${field(tr('imageQuantity'),'imageCount','number','1','required min="0" max="5000" step="1"')}${field(tr('price'),'price','number','10.00','required min="0.01" max="10000" step="0.01"')}<button class="portal-btn" type="submit">${esc(tr('addPackage'))}</button></form><ul class="portal-admin-list">${packages.length?packages.map(pkg=>`<li><span>${esc(pkg.name)}<small>${esc(tr(pkg.imageCount===0?'packageAll':'packageCount',{n:pkg.imageCount}))}</small></span><strong>${esc(money(pkg.priceCents,pkg.currency))}</strong></li>`).join(''):`<li>${esc(tr('noPackages'))}</li>`}</ul></section><section class="portal-card"><h3>${esc(tr('photos'))} (${images.length})</h3><p class="portal-small">${esc(tr('uploadIntro'))}</p><form id="portal-upload-form"><div class="portal-upload">${icon('image')}<label class="portal-field" for="p-upload"><span>${esc(tr('selectFiles'))}</span><input type="file" name="photos" id="p-upload" accept="image/jpeg,image/png,image/webp" multiple required></label><button class="portal-btn" type="submit">${esc(tr('upload'))}${icon('plus')}</button></div></form><div class="portal-admin-thumbs">${images.map(image=>`<div class="portal-admin-thumb"><img src="${esc(image.previewUrl)}" alt="${esc(image.title||'')}" loading="lazy"><label><input type="checkbox" data-admin-image="${esc(image.id)}" ${state.adminSelection.has(image.id)?'checked':''}><span>${esc(image.title||image.id)}</span></label></div>`).join('')}</div><div class="portal-release"><div style="width:100%"><h3>${esc(tr('releaseTitle'))}</h3><p class="portal-small">${esc(tr('releaseIntro'))}</p></div><div class="portal-field"><label for="p-release-user">${esc(tr('chooseCustomer'))}</label><select id="p-release-user"><option value="">${esc(tr('chooseCustomer'))}</option>${members.map(member=>`<option value="${esc(member.id)}">${esc(member.name||member.email)}</option>`).join('')}</select></div>${btn(tr('release'),'admin-release',state.adminSelection.size&&members.length?'':'disabled','','download')}</div></section>`;
}
function adminOrdersHtml(){
  return `<section class="portal-admin-orders">${state.adminOrders.length?`<div class="portal-order-list">${state.adminOrders.map(order=>`<article class="portal-order"><div><h3>${esc(order.galleryName||'')} · ${esc(order.packageName||'')}</h3><p>${esc(tr('orderNumber',{id:order.id}))} · ${esc(fmtDate(order.createdAt))}</p>${order.customerEmail?`<p>${esc(order.customerName||'')} · ${esc(order.customerEmail)}</p>`:''}<p>${esc(tr('images',{n:order.imageIds?.length||0}))} · ${esc(tr(order.paymentMethod||'transfer'))}</p>${order.withdrawalRequested?`<span class="portal-badge">${esc(tr('withdrawalRequested'))}</span>`:''}</div><div class="portal-order-meta"><strong>${esc(money(order.amountCents,order.currency))}</strong><span class="portal-badge ${orderStatus(order)==='orderPaid'?'paid':''}">${esc(tr(orderStatus(order)))}</span></div>${orderStatus(order)==='orderPending'&&order.paymentMethod==='transfer'?btn(tr('markPaid'),'mark-paid',`data-id="${esc(order.id)}"`,'secondary','check'):''}${order.status==='paid'&&!order.receiptSent?btn(tr('resendReceipt'),'retry-receipt',`data-id="${esc(order.id)}"`,'secondary','mail'):''}${order.status==='paid'&&order.withdrawalRequested?btn(tr('markRefunded'),'mark-refunded',`data-id="${esc(order.id)}"`,'secondary'):''}</article>`).join('')}</div>`:`<section class="portal-empty"><h2>${esc(tr('manageOrders'))}</h2><p>${esc(tr('noOrders'))}</p></section>`}</section>`;
}
function editPackageDialog(id){const pkg=state.adminDetail.packages.find(item=>item.id===id);if(!pkg)return;createDialog(`<div class="portal-modal-copy">${dialogTop(tr('edit'))}<form id="portal-edit-package" data-id="${esc(pkg.id)}">${field(tr('packageName'),'packageName','text',pkg.name,'required maxlength="100"')}${field(tr('imageQuantity'),'imageCount','number',pkg.imageCount,'required min="0" max="5000" step="1"')}${field(tr('price'),'price','number',(pkg.priceCents/100).toFixed(2),'required min="0.01" max="10000" step="0.01"')}<label class="portal-check"><input type="checkbox" name="active" ${pkg.active!==false?'checked':''}><span>${esc(tr('activePackage'))}</span></label><button type="submit" class="portal-btn block">${esc(tr('save'))}</button></form></div>`);}
function createGalleryDialog(){createDialog(`<div class="portal-modal-copy">${dialogTop(tr('createGallery'))}<form id="portal-create-gallery">${field(tr('galleryName'),'name','text','','required maxlength="160"')}${field(tr('galleryDate'),'date','date','','required')}${galleryControls()}<p class="portal-small" id="p-create-pricing-hint">${esc(tr('galleryPricingIntro'))}</p><button class="portal-btn block" type="submit">${esc(tr('create'))}${icon('plus')}</button></form></div>`);}
async function makePreview(file){
  if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('UI:'+tr('uploadType'));
  if(file.size>30*1024*1024)throw new Error('UI:'+tr('uploadSize'));
  const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});
  try{if(bitmap.width*bitmap.height>50000000)throw new Error('UI:'+tr('uploadPixels'));const ratio=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise((resolve,reject)=>canvas.toBlob(result=>result?resolve(result):reject(new Error('Preview failed')),'image/webp',.85));return{blob,width:bitmap.width,height:bitmap.height};}finally{bitmap.close();}
}
function expiryInVienna(date){if(!date)return null;const label=new Intl.DateTimeFormat('en',{timeZone:'Europe/Vienna',timeZoneName:'shortOffset'}).formatToParts(new Date(date+'T12:00:00Z')).find(part=>part.type==='timeZoneName')?.value||'GMT+1';const parts=label.match(/GMT([+-])(\d+)(?::(\d+))?/);const offset=parts?parts[1]+parts[2].padStart(2,'0')+':'+(parts[3]||'00'):'+01:00';return date+'T23:59:59'+offset;}
async function uploadImages(form){
  const files=[...form.elements.photos.files];if(!files.length)return;
  let uploaded=0;
  for(const [index,file] of files.entries()){message(form,tr('uploading',{name:file.name,n:index+1,total:files.length}),'');const preview=await makePreview(file),data=new FormData();data.set('preview',preview.blob,file.name.replace(/\.[^.]+$/,'.webp'));data.set('original',file,file.name);data.set('title',file.name.replace(/\.[^.]+$/,''));data.set('width',preview.width);data.set('height',preview.height);await api(`/admin/galleries/${encodeURIComponent(state.adminGalleryId)}/images`,{method:'POST',body:data});uploaded++;}
  await loadAdmin();toast(tr('uploadDone',{n:uploaded}));
}

async function onSubmit(event){
  const form=event.target;if(!form.matches('form[id^="portal-"]'))return;event.preventDefault();if(!form.reportValidity())return;
  const data=new FormData(form),values=Object.fromEntries(data.entries());
  await withBusy(form,async()=>{
    switch(form.id){
      case 'portal-login-form':if(state.authMode==='login'){await api('/auth/login',{method:'POST',body:{email:values.email,password:values.password}});await loadSession();if(pendingGallery)await openGallery(pendingGallery);else await loadHome();}else{await api('/auth/request',{method:'POST',body:{email:values.email,purpose:state.authMode==='reset'?'reset':'setup'}});message(form,tr('requestSent'),'success');}break;
      case 'portal-password-form':if(values.password!==values.passwordRepeat)throw new Error('UI:'+tr('passwordMismatch'));if(values.password.length<12)throw new Error('UI:'+tr('passwordShort'));await api('/auth/complete',{method:'POST',body:{token:authToken,password:values.password}});await loadSession();if(pendingGallery)await openGallery(pendingGallery);else await loadHome();toast(tr('setupDone'));break;
      case 'portal-order-form':{
        const selectedPackage=state.detail.packages.find(pkg=>pkg.id===values.packageId),wholeGallery=selectedPackage?.imageCount===0;
        if(!wholeGallery&&state.selected.size>500)throw new Error('UI:'+tr('selectionLimit'));
        const result=await api('/orders',{method:'POST',body:{galleryId:state.detail.gallery.id,...(wholeGallery?{all:true}:{imageIds:[...state.selected]}),packageId:values.packageId,paymentMethod:values.paymentMethod,termsAccepted:data.has('termsAccepted'),digitalConsent:data.has('digitalConsent')}});
        const orders=await api('/orders');state.orders=orders.orders||[];closeDialog();renderGallery();if(result.paymentUrl){const url=new URL(result.paymentUrl);if(url.protocol!=='https:')throw new Error('UI:'+tr('errorConfig'));location.assign(url.href);}else showBank(result.order);break;
      }
      case 'portal-create-gallery':{const result=await api('/admin/galleries',{method:'POST',body:{name:values.name,date:values.date||null,shootingType:values.shootingType,pricingMode:values.pricingMode}});closeDialog();await loadAdmin(result.gallery.id);break;}
      case 'portal-gallery-settings':await api(`/admin/galleries/${encodeURIComponent(state.adminGalleryId)}`,{method:'PATCH',body:{name:values.name,date:values.date||null,description:values.description||'',coverImageId:values.coverImageId||null,expiresAt:expiryInVienna(values.expiresAt),published:data.has('published'),shootingType:values.shootingType,pricingMode:values.pricingMode,theme:values.theme,gridLayout:values.gridLayout,coverPosition:Number(values.coverPosition)}});await loadAdmin();toast(tr('gallerySaved'));break;
      case 'portal-member-form':await api(`/admin/galleries/${encodeURIComponent(state.adminGalleryId)}/members`,{method:'POST',body:{email:values.memberEmail,name:values.memberName}});await loadAdmin();toast(tr('accessAdded'));break;
      case 'portal-package-form':await api(`/admin/galleries/${encodeURIComponent(state.adminGalleryId)}/packages`,{method:'POST',body:{name:values.packageName,imageCount:Number(values.imageCount),priceCents:Math.round(Number(values.price)*100),currency:'EUR'}});await loadAdmin();toast(tr('packageAdded'));break;
      case 'portal-edit-package':await api(`/admin/galleries/${encodeURIComponent(state.adminGalleryId)}/packages/${encodeURIComponent(form.dataset.id)}`,{method:'PATCH',body:{name:values.packageName,imageCount:Number(values.imageCount),priceCents:Math.round(Number(values.price)*100),active:data.has('active')}});closeDialog();await loadAdmin();toast(tr('gallerySaved'));break;
      case 'portal-upload-form':await uploadImages(form);break;
    }
  });
}
async function onAction(event){
  const target=event.target.closest('[data-action]');if(!target)return;event.preventDefault();const action=target.dataset.action;
  try{
    switch(action){
      case 'retry':await initialise();break;
      case 'show-password':{const input=document.getElementById(target.dataset.input);input.type=input.type==='password'?'text':'password';target.setAttribute('aria-pressed',input.type==='text');target.setAttribute('aria-label',tr(input.type==='text'?'hidePassword':'showPassword'));break;}
      case 'auth-mode':state.authMode=target.dataset.mode;renderLogin();document.querySelector('input[name="email"]')?.focus();break;
      case 'logout':await state.favouriteQueue.catch(()=>{});await api('/auth/logout',{method:'POST'});closeDialog();state.user=null;state.csrf=null;state.detail=null;state.admin=false;state.selected.clear();state.favourites.clear();renderLogin();break;
      case 'home':params.delete('gallery');history.replaceState(null,'',location.pathname+(params.size?'?'+params:'')+location.hash);await loadHome();break;
      case 'open-gallery':await openGallery(target.dataset.id);break;
      case 'filter':state.filter=target.dataset.filter;renderGallery();break;
      case 'select-image':toggleSelected(target.dataset.id);break;
      case 'favorite':toggleFavourite(target.dataset.id);break;
      case 'select-all':visibleImages().forEach(image=>state.selected.add(image.id));syncSelectionUI();break;
      case 'buy-gallery':state.detail.images.forEach(image=>state.selected.add(image.id));syncSelectionUI();openCheckout();break;
      case 'clear-selection':state.selected.clear();syncSelectionUI();break;
      case 'open-lightbox':openLightbox(target.dataset.id);break;
      case 'close-dialog':closeDialog();break;
      case 'previous':moveLightbox(-1);break;
      case 'next':moveLightbox(1);break;
      case 'lightbox-favorite':toggleFavourite(state.lightboxList[state.lightboxIndex].id);break;
      case 'lightbox-select':toggleSelected(state.lightboxList[state.lightboxIndex].id);break;
      case 'fullscreen':if(document.fullscreenElement)await document.exitFullscreen();else if(activeDialog?.requestFullscreen)await activeDialog.requestFullscreen();break;
      case 'download':await downloadSelection();break;
      case 'checkout':openCheckout();break;
      case 'order-bank':{const order=state.orders.find(item=>item.id===target.dataset.id);if(order)showBank(order);break;}
      case 'save-bank-qr':{const canvas=activeDialog?.querySelector('#p-bank-qr');if(canvas)canvas.toBlob(blob=>{if(blob)downloadBlob(blob,'LiZa-Ueberweisung.png');},'image/png');break;}
      case 'withdraw':if(confirm(tr('withdrawalConfirm'))){target.disabled=true;try{await api(`/orders/${encodeURIComponent(target.dataset.id)}/withdraw`,{method:'POST',body:{confirmed:true}});if(state.detail)await openGallery(state.detail.gallery.id);else await loadHome();toast(tr('withdrawalSaved'));}finally{if(target.isConnected)target.disabled=false;}}break;
      case 'toggle-admin':if(state.admin){state.admin=false;await loadHome();}else await loadAdmin();break;
      case 'admin-tab':state.adminTab=target.dataset.tab;await loadAdmin();break;
      case 'admin-gallery':state.adminSelection.clear();await loadAdmin(target.dataset.id);break;
      case 'admin-select-all':state.adminDetail.images.forEach(image=>state.adminSelection.add(image.id));syncAdminSelection();break;
      case 'admin-clear-selection':state.adminSelection.clear();syncAdminSelection();break;
      case 'create-gallery':createGalleryDialog();break;
      case 'edit-package':editPackageDialog(target.dataset.id);break;
      case 'revoke-member':if(confirm(tr('revokeConfirm'))){target.disabled=true;try{await api(`/admin/galleries/${encodeURIComponent(state.adminGalleryId)}/members/${encodeURIComponent(target.dataset.id)}`,{method:'DELETE'});await loadAdmin();toast(tr('revoked'));}finally{if(target.isConnected)target.disabled=false;}}break;
      case 'invite':target.disabled=true;try{await api(`/admin/galleries/${encodeURIComponent(state.adminGalleryId)}/invite`,{method:'POST',body:{email:target.dataset.email}});toast(tr('inviteSent'));}finally{target.disabled=false;}break;
      case 'admin-release':{const userId=document.querySelector('#p-release-user').value;if(!userId||!state.adminSelection.size)return toast(tr('formInvalid'));const wholeGallery=state.adminSelection.size===state.adminDetail.images.length;if(!wholeGallery&&state.adminSelection.size>500)return toast(tr('selectionLimit'));target.disabled=true;try{await api(`/admin/galleries/${encodeURIComponent(state.adminGalleryId)}/release`,{method:'POST',body:{userId,...(wholeGallery?{all:true}:{imageIds:[...state.adminSelection]})}});state.adminSelection.clear();await loadAdmin();toast(tr('releaseSuccess'));}finally{if(target.isConnected)target.disabled=false;}break;}
      case 'mark-paid':if(confirm(tr('paidConfirm'))){target.disabled=true;try{await api(`/admin/orders/${encodeURIComponent(target.dataset.id)}/paid`,{method:'POST'});await loadAdmin();toast(tr('paidSuccess'));}finally{if(target.isConnected)target.disabled=false;}}break;
      case 'retry-receipt':target.disabled=true;try{await api(`/admin/orders/${encodeURIComponent(target.dataset.id)}/receipt`,{method:'POST'});await loadAdmin();toast(tr('inviteSent'));}finally{if(target.isConnected)target.disabled=false;}break;
      case 'mark-refunded':if(confirm(tr('refundConfirm'))){target.disabled=true;try{await api(`/admin/orders/${encodeURIComponent(target.dataset.id)}/refunded`,{method:'POST'});await loadAdmin();toast(tr('refundedSaved'));}finally{if(target.isConnected)target.disabled=false;}}break;
    }
  }catch(error){toast(errorText(error));if(error instanceof ApiError&&error.status===401&&state.user){state.user=null;renderLogin();}}
}
function syncAdminSelection(){document.querySelectorAll('[data-admin-image]').forEach(input=>input.checked=state.adminSelection.has(input.dataset.adminImage));const release=document.querySelector('[data-action="admin-release"]');if(release)release.disabled=!state.adminSelection.size||!state.adminDetail.members?.length;const counter=document.querySelector('#p-admin-selection-count');if(counter)counter.textContent=tr('selectedCount',{n:state.adminSelection.size});}
function onChange(event){
  const form=event.target.closest('form');
  if(event.target.name==='shootingType'&&form?.elements.pricingMode){form.elements.pricingMode.value=event.target.value==='school'?'images':'gallery';}
  if(['shootingType','pricingMode'].includes(event.target.name)){const hint=form?.querySelector('#p-create-pricing-hint');if(hint)hint.textContent=tr(form.elements.pricingMode.value==='images'?'schoolPricingIntro':'galleryPricingIntro');}
  if(event.target.matches('[data-admin-image]')){const id=event.target.dataset.adminImage;if(event.target.checked)state.adminSelection.add(id);else state.adminSelection.delete(id);syncAdminSelection();}
}
app.addEventListener('click',onAction);app.addEventListener('submit',onSubmit);app.addEventListener('change',onChange);
async function initialise(){
  app.setAttribute('aria-busy','true');
  try{
    await loadSession();
    if(authToken){renderSetPassword();return;}
    if(!state.user){if(state.capabilities.configured===false){renderOffline();return;}renderLogin();return;}
    const paypalOrder=params.get('paypalOrder');
    if(paypalOrder){await api('/orders/'+encodeURIComponent(paypalOrder)+'/capture',{method:'POST'});params.delete('paypalOrder');params.delete('token');params.delete('PayerID');history.replaceState(null,'',location.pathname+(params.size?'?'+params:'')+location.hash);toast(tr('paymentProcessing'));}
    if(pendingGallery)await openGallery(pendingGallery);else await loadHome();
  }catch(error){renderOffline();}
}
document.title=tr('title')+' | LiZa Memories Photography';
initialise();
